'use strict';

/**
 * Validates that an object conforms to the GameKit Storage Adapter interface.
 * Must implement get, set, delete, and list methods.
 * 
 * @param {object} adapter 
 * @throws {TypeError} If the adapter does not conform to the interface.
 */
function validateStorageAdapter(adapter) {
  if (!adapter || typeof adapter !== 'object') {
    throw new TypeError('Storage adapter must be an object implementing get, set, delete, and list');
  }

  const requiredMethods = ['get', 'set', 'delete', 'list'];
  for (const method of requiredMethods) {
    if (typeof adapter[method] !== 'function') {
      throw new TypeError(`Storage adapter is missing required method: "${method}()"`);
    }
  }
}

module.exports = {
  validateStorageAdapter
};
